từ chối trùng cần kiểm tra hoặc dùng thao tác phù hợp. java.util.Map<String, String> products = new java.util.HashMap<>();
products.put("P01", "Bút");
if (products.putIfAbsent("P01", "Vở") != null) {
    System.out.println("Mã đã tồn tại");
}
